use std::fs
use std::env
use std::process

fn emit(content: string, number: bool, counter: int) -> int {
    let mut n: int = counter
    if !number {
        print(content)
        return n
    }
    let mut parts: Vec<string> = content.split("\n").collect()
    if parts.len() > 0 && parts[parts.len() - 1] == "" {
        parts.pop()
    }
    for p in parts {
        n += 1
        println("${n:>6}\t${p}")
    }
    n
}

fn main() {
    let mut number = false
    let mut files: Vec<string> = []
    let mut first = true
    for a in env::args() {
        if first {
            first = false
        } else if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
    }
    let mut counter: int = 0
    let mut status: int = 0
    if files.len() == 0 {
        let text = fs::read_to_string("/dev/stdin").unwrap_or("")
        counter = emit(text, number, counter)
    } else {
        for f in files {
            match fs::read_to_string(f) {
                Ok(text) => { counter = emit(text, number, counter) },
                Err(_) => {
                    println("cat: ${f}: No such file")
                    status = 1
                },
            }
        }
    }
    process::exit(status)
}

